import {create,validate,edges,simulate,stateAt,COUNT} from './engine.js?v=0.18.0';
const clone=structuredClone;
export const NETWORKS={groups:'Two dense groups',mixed:'Mixed ring · same degree',hub:'Hub and spokes',custom:'Your connections'};
export const KEY='thinking-lab:adoption:v1';
export function switchNetwork(s,network){if(!['groups','mixed','hub'].includes(network))throw Error('Choose a network preset.');const next={...clone(s),network,bridge:false};delete next.links;delete next.layout;return validate(next);}
export function toggleLink(s,a,b){if(a===b)throw Error('Choose two different people.');const next=clone(s),key=[a,b].sort((a,b)=>a-b),links=edges(s),found=links.findIndex(x=>x[0]===key[0]&&x[1]===key[1]);if(found<0)links.push(key);else links.splice(found,1);next.layout=s.network==='custom'?(s.layout||'groups'):(s.network||'groups');next.network='custom';next.bridge=false;next.links=links;return validate(next);}
export function placement(s,kind,count=s.seeds.length){if(!Number.isInteger(count)||count<0||count>COUNT)throw Error('Pilot size must be between 0 and 12.');const ids=Array.from({length:COUNT},(_,i)=>i),degree=ids.map(i=>edges(s).filter(e=>e.includes(i)).length);let order;if(kind==='concentrate')order=ids;else if(kind==='spread')order=[0,6,1,7,2,8,3,9,4,10,5,11];else if(kind==='connected')order=ids.sort((a,b)=>degree[b]-degree[a]||a-b);else throw Error('Unknown placement rule.');return {...clone(s),seeds:order.slice(0,count)};}
export function differences(a,b){if(!b)return [];const result=[];if(JSON.stringify([...a.seeds].sort((a,b)=>a-b))!==JSON.stringify([...b.seeds].sort((a,b)=>a-b)))result.push(a.seeds.length===b.seeds.length?'pilot location':'pilot size and location');const links=x=>JSON.stringify(edges(x).map(p=>p.join('-')).sort());if(links(a)!==links(b))result.push('connections');for(const [k,label] of [['benefit','standalone benefit'],['coordination','coordination value'],['switching','switching friction'],['compatibility','compatibility'],['hold','pilot commitment']])if(a[k]!==b[k])result.push(label);return result;}
export function positions(s){const network=s.network==='custom'?(s.layout||'groups'):(s.network||'groups');if(network==='groups')return Array.from({length:COUNT},(_,i)=>{const a=i%6*Math.PI/3-Math.PI/2;return{x:(i<6?25:75)+Math.cos(a)*17,y:50+Math.sin(a)*33};});return Array.from({length:COUNT},(_,i)=>{if(network==='hub'&&i===0)return{x:50,y:50};const a=(network==='hub'?(i-1)/11:i/12)*Math.PI*2-Math.PI/2;return{x:50+Math.cos(a)*38,y:50+Math.sin(a)*37};});}
export function validateBundle(raw){const b=clone(raw);if(!b||typeof b!=='object')throw Error('Choose an Adoption experiment.');validate(b.s);if(b.baseline)validate(b.baseline);else b.baseline=null;b.round??=0;b.selected??=2;b.mode??='pilot';b.decision??='';if(!Number.isInteger(b.round)||b.round<0||b.round>24||!Number.isInteger(b.selected)||b.selected<0||b.selected>=COUNT||!['pilot','inspect','connect'].includes(b.mode)||typeof b.decision!=='string'||b.decision.length>20000)throw Error('Invalid inspection or decision state.');b.round=Math.min(b.round,Math.max(simulate(b.s).rounds,b.baseline?simulate(b.baseline).rounds:0));return {s:b.s,baseline:b.baseline,round:b.round,selected:b.selected,mode:b.mode,decision:b.decision};}
export const initialBundle=()=>validateBundle({s:create()});
export function portable(b){return JSON.stringify({kind:'adoption',version:2,...validateBundle(b)},null,2);}
export function parse(text){const b=JSON.parse(text);if(b.kind!=='adoption'||b.version!==2)throw Error('Choose an exported Adoption experiment.');return validateBundle(b);}
export function markdown(b){b=validateBundle(b);const r=simulate(b.s),p=b.baseline?simulate(b.baseline):null,now=stateAt(r,b.round),pinned=p?stateAt(p,b.round):null;return `# Crossing the adoption gap\n\nNetwork: ${NETWORKS[b.s.network||'groups']}; ${edges(b.s).length} connections. Inspected round ${b.round}. Current trajectory: ${r.status}${r.status==='cycle'?` (${r.cycleLength}-round cycle)`:''}.\n\n${p?`Differences from pinned plan: ${differences(b.s,b.baseline).join(', ')||'none'}.\n\n`:''}| Person | Current at round ${b.round} | Pinned at same round |\n|---|---|---|\n${now.map((v,i)=>`| ${String(i+1).padStart(2,'0')} | ${v?'New':'Old'} | ${pinned?(pinned[i]?'New':'Old'):'—'} |`).join('\n')}\n\nDecision / next question: ${b.decision||'Not recorded.'}\n\nFictional deterministic coordination, fixed personal differences, simultaneous choices. Isolated people get no coordination utility. Repeated patterns are cycles, not stable outcomes.\n\n\`\`\`json\n${JSON.stringify({experiment:JSON.parse(portable(b)),result:r,pinnedResult:p},null,2)}\n\`\`\`\n`;}
